        lc_vec[i] = (float)(lc_fm[0][i] / 9.81); lc_vec[3 + i] = (float)lc_gm[0][i];
        lc_vec[6 + i] = (float)(lc_fm[1][i] / 9.81); lc_vec[9 + i] = (float)lc_gm[1][i];
        double dv = lc_Rs[i] * (lc_V5[0] - lc_Vs[0]) + lc_Rs[3 + i] * (lc_V5[1] - lc_Vs[1]) + lc_Rs[6 + i] * (lc_V5[2] - lc_Vs[2]);
