    for (int i = 0; i < 3; i++) for (int j = 0; j < 3; j++) { double a = 0; for (int k = 0; k < 3; k++) a += lc_Rs[3 * k + i] * lc_R5[3 * k + j]; Rb[3 * i + j] = a; }
