                for (int j = 0; j < MAP_PS; j++) {
                    const uint8_t *wrow = I + (cv + dy - r + j) * w + cu + dx - r, *trow = m->t + j * MAP_PS;
                    for (int i = 0; i < MAP_PS; i++) { double q = wrow[i]; sw1 += q; sw2 += q * q; sd += (trow[i] - tm) * q; }
                }
