            for (int dx = -S; dx <= S; dx++)
                if ((abs(dx - bx) > 2 || abs(dy - by) > 2) && cc[(dy + S) * sw + dx + S] > second) second = cc[(dy + S) * sw + dx + S];
        if (best < MAP_ZNCC || best - second < 0.04) continue;
        mp_match++;
